const byKey = new Map<string, MembersQuestContent>();
const byName = new Map<string, MembersQuestContent>();
for (const content of MEMBERS_QUEST_CONTENT) {
    if (byKey.has(content.key) || byName.has(content.displayName.toLowerCase())) {
        throw new Error(`Duplicate members quest content: ${content.displayName}`);
    }
    byKey.set(content.key, content);
    byName.set(content.displayName.toLowerCase(), content);
}

export function getMembersQuestContent(reference: string): MembersQuestContent | undefined {
    const key = String(reference ?? "").trim().toLowerCase();
    return byKey.get(key) ?? byName.get(key);
}

export const buildMembersQuestJournal = buildFreeToPlayQuestJournal;
export const buildMembersQuestOverview = buildFreeToPlayQuestOverview;
